//! The legend's keys (gui_state_contract §2; render_gui_spec §G6; R-72, R-390 "Contract fields"): what the engine side
//! sends for the Legend to draw, generated by evaluating the stain. The GUI holds no key of its own; it draws these, one
//! per dimension, in the order received. The real engine's evaluation is TASK-M8-22's (REQ-GUI-105, REQ-GUI-106);
//! until then its snapshot carries no key.
//!
//! The "not yet" style and the outcome palette are re-exported here, so the GUI draws a `running` key as the style
//! (R-399), from the one source of their calibrations (REQ-COL-053, REQ-COL-064; colour_composition §1.4), through the
//! contract it is allowed to reach.

pub use render::colour::outcome::{Swatch, SWATCHES};
pub use render::present::{
    debug_not_yet, not_yet_dot_at, NOT_YET_CELL, NOT_YET_DOT, NOT_YET_DOT_SRGB8, NOT_YET_SRGB8,
};

/// The keys of the stain on show, one per dimension, in the order the evaluation walks back from OUT (render_gui_spec
/// §G6): the colour dimension's first, then what brightness, or any second channel, encodes.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Legend {
    /// The keys, in order.
    pub keys: Vec<LegendKey>,
}

/// One dimension's key (render_gui_spec §G6). The kinds §G6 lists beyond these (direction, coordinate, post line
/// samples, ticks through a curve) join with TASK-M8-22's evaluation.
#[derive(Clone, Debug, PartialEq)]
pub enum LegendKey {
    /// Categorical: swatches, with their shares of the view.
    Categorical {
        /// What the dimension is, e.g. "colour · outcome class".
        title: String,
        /// The classes, in the stain's order.
        entries: Vec<LegendEntry>,
    },
    /// A bar: what a second channel (brightness, say) encodes over its declared input domain (R-53).
    Ramp {
        /// What the dimension is, e.g. "brightness · t_end (late fade)".
        title: String,
        /// The domain's low end.
        lo: f64,
        /// The domain's high end.
        hi: f64,
        /// What the low end reads as, e.g. "full".
        lo_note: String,
        /// What the high end reads as, e.g. "darkest".
        hi_note: String,
        /// The channel sampled at equal steps over `[lo, hi]`, pushed through the combiner: 8-bit sRGB.
        samples: Vec<[u8; 3]>,
    },
}

/// One class of a categorical key.
#[derive(Clone, Debug, PartialEq)]
pub struct LegendEntry {
    /// Its label, 0-based (R-22).
    pub label: String,
    /// How it is drawn.
    pub swatch: SwatchStyle,
    /// Its share of the view, in percent.
    pub share: f64,
}

/// How a class is drawn: a flat colour, or the "not yet" style, never flat (R-399).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SwatchStyle {
    /// One flat colour, 8-bit sRGB.
    Flat([u8; 3]),
    /// The "not yet" style: [`debug_not_yet`], the grey with a fine dot stipple from the pixel position.
    NotYet,
}
